#include "hip_api.h"
#include <thread>
#include <cstdio>
int main(int argc,char**argv){try{hip_probe::Api api;api.Check(api.hipInit(0),"init");int count=0;api.Check(api.hipGetDeviceCount(&count),"count");using Get=int(*)(int*);Get get{};api.Load(get,"hipGetDevice");int initial=-1;get(&initial);printf("devices=%d initial=%d\n",count,initial);int chosen=-1;for(int i=0;i<count;i++){char name[256]{};api.hipDeviceGetName(name,256,i);auto p=api.Properties(i);printf("device=%d name=%s arch=%s\n",i,name,p.gcnArchName);if(std::string(p.gcnArchName).find("gfx1201")==0)chosen=i;}if(chosen<0||argc<2)return 2;hip_probe::Handle module{},fn{};std::thread init([&]{api.Check(api.hipSetDevice(chosen),"init device");api.Check(api.LoadModule(&module,argv[1]),"module");int current=-1;get(&current);printf("init_thread device=%d\n",current);});init.join();int before=-1;get(&before);int old=api.hipModuleGetFunction(&fn,module,"c32_wave1_prefix_b8d");printf("other_thread before=%d target=%d get_function=%d\n",before,chosen,old);api.Check(api.hipSetDevice(chosen),"enqueue bind");get(&before);int fixed=api.hipModuleGetFunction(&fn,module,"c32_wave1_prefix_b8d");printf("other_thread after=%d get_function=%d\n",before,fixed);api.hipModuleUnload(module);return fixed?1:0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
